{"id":"146f7094-f0a2-453b-9d83-c6956457476b","inserted_at":"2026-07-14T22:54:58.682612+00:00","updated_at":"2026-07-14T22:54:58.682612+00:00","type":"sql","name":"Untitled query","description":"","content":{"sql":"-- 1. Aggiunta delle colonne mancanti richieste dal frontend e dalla funzione get_pois()\r\nALTER TABLE public.pois ADD COLUMN IF NOT EXISTS crowd_level INTEGER DEFAULT 20;\r\nALTER TABLE public.pois ADD COLUMN IF NOT EXISTS has_water BOOLEAN DEFAULT false;\r\nALTER TABLE public.pois ADD COLUMN IF NOT EXISTS p_iva TEXT;\r\n\r\n-- 2. Ricreazione sicura dell'RPC get_pois() che stava andando in crash\r\nDROP FUNCTION IF EXISTS get_pois();\r\n\r\nCREATE FUNCTION get_pois()\r\nRETURNS TABLE (\r\n    id UUID,\r\n    name TEXT,\r\n    category TEXT,\r\n    layer_name TEXT,\r\n    xp_reward INTEGER,\r\n    checkin_radius INTEGER,\r\n    crowd_level INTEGER,\r\n    has_water BOOLEAN,\r\n    is_accessible BOOLEAN,\r\n    latitude FLOAT8,\r\n    longitude FLOAT8,\r\n    p_iva TEXT\r\n) AS $$\r\nBEGIN\r\n    RETURN QUERY\r\n    SELECT \r\n        p.id, \r\n        p.name, \r\n        p.category, \r\n        p.layer_name, \r\n        p.xp_reward, \r\n        p.checkin_radius,\r\n        p.crowd_level,\r\n        p.has_water,\r\n        p.is_accessible,\r\n        ST_Y(p.coords::geometry) as latitude,\r\n        ST_X(p.coords::geometry) as longitude,\r\n        p.p_iva\r\n    FROM public.pois p\r\n    WHERE p.is_active = true\r\n    ORDER BY p.name ASC;\r\nEND;\r\n$$ LANGUAGE plpgsql SECURITY DEFINER;","content_id":"146f7094-f0a2-453b-9d83-c6956457476b","schema_version":"1.0"},"visibility":"user","favorite":false,"project":{"id":27102476,"ref":"fsuolbwsvpgiglwcaffh","name":"loto.hub","base_project_id":null},"owner":{"id":10709404,"username":"lototaranto-alt"},"updated_by":{"id":10709404,"username":"lototaranto-alt"},"message":""}
